Here’s a simplified implementation of a lock-free linked list using hazard pointers in C++: 

```cpp
#include <atomic>
#include <vector>
#include <memory>

template<typename T>
struct Node {
    T data;
    Node *next;
    Node(T v) : data(v), next(nullptr) {}
};

template<typename T>
class LockFreeList {
    Node<T>* head;
    std::vector<std::atomic<Node<T>*>> hazard;

public:
    LockFreeList() : head(nullptr) {
        hazard.resize(std::thread::hardware_concurrency());
    }

    bool insert(T value) {
        Node<T>* newNode = new Node<T>(value);
        while (true) {
            Node<T>* oldHead = head;
            newNode->next = oldHead;
            if (head.compare_exchange_strong(oldHead, newNode)) {
                return true;
            }
        }
    }

    bool remove(T value) {
        Node<T>* oldHead;
        while (true) {
            // Lock hazard pointer
            Node<T>* current = head.load();
            hazard[0] = current; // thread's hazard pointer
            if (current == nullptr) return false;
            if (current->data == value) {
                Node<T>* nextNode = current->next;
                // Attempt to remove
                if (head.compare_exchange_strong(current, nextNode)) {
                    // Memory management placeholder for reclamation
                    delete current;
                    return true;
                }
            }
            head.load(); // to validate
        }
    }
};
```

