            [A[1][0] * B[0][0] + A[1][1] * B[1][0], A[1][0] * B[0][1] + A[1][1] * B[1][1]]]

function matrixPower(M, p):
    if p == 1:
        return M
    if p % 2 == 0:
        halfPower = matrixPower(M, p / 2)
        return matrixMultiply(halfPower, halfPower)
    else:
